// ---- the player reports (the game's flag next to a player at the end of a match: net/oyuncuSikayet.ts) -------------
/** logs/oyuncu_sikayet/<key> = { r: uid, rt: browser id, ad, by, byt, m: the game, oda, sebep: [ids], not, t,
 *  kanit: { foto: [small jpeg data urls], ses: [{ k: 'dublaj' | 'kulak', v: the sound's record }] } } */
export interface OyuncuSikayet {
  key: string;
  r: string;
  rt: string;
  ad: string;
  by: string;
  byt: string;
  m: string;
  oda: string;
  sebep: string[];
  not: string;
  t: number;
  foto: string[];
  ses: { k: string; v: Record<string, unknown> }[];
}

/** the database gives a list back as an object with the keys 0, 1, 2 ... */
export const listeOf = (v: unknown): unknown[] =>
  Array.isArray(v)
    ? v
    : v && typeof v === 'object'
      ? Object.keys(v as Record<string, unknown>)
          .sort((a, b) => Number(a) - Number(b))
          .map((k) => (v as Record<string, unknown>)[k])
      : [];

export function oyuncuSikayetleriIzle(cb: (list: OyuncuSikayet[]) => void): () => void {
  return onValue(
    ref(db(), 'logs/oyuncu_sikayet'),
    (s) => {
      const v = (s.val() ?? {}) as Record<string, Record<string, unknown>>;
      cb(
        Object.entries(v)
          .filter(([, r]) => r && typeof r === 'object')
          .map(([key, r]) => {
            const k = (r.kanit ?? {}) as Record<string, unknown>;
            return {
              key,
              r: String(r.r ?? ''),
              rt: String(r.rt ?? ''),
              ad: String(r.ad ?? 'Oyuncu'),
              by: String(r.by ?? ''),
              byt: String(r.byt ?? ''),
              m: String(r.m ?? ''),
              oda: String(r.oda ?? ''),
              sebep: listeOf(r.sebep).map(String),
              not: String(r.not ?? ''),
              t: Number(r.t) || 0,
              foto: listeOf(k.foto).filter((x): x is string => typeof x === 'string' && x.startsWith('data:image')),
              ses: listeOf(k.ses)
                .filter((x): x is { k: string; v: Record<string, unknown> } => !!x && typeof x === 'object' && !!(x as { v?: unknown }).v)
                .map((x) => ({ k: String(x.k ?? ''), v: x.v })),
            };
          })
          .sort((a, b) => b.t - a.t)
      );
    },
    () => cb([])
  );
}

/** the reports are decided: they and their evidence go (no space wasted) */
export async function oyuncuSikayetKapat(keys: string[]): Promise<void> {
  for (const k of keys) await remove(ref(db(), `logs/oyuncu_sikayet/${k}`));
}

/** a ban: onayli/ban/<browser id> = { until: ms (0 = for ever), sebep, ad, t } - the game asks it before a room (net/ban.ts) */
export interface Ban {
  tid: string;
  until: number;
  sebep: string;
  ad: string;
  t: number;
}
export function banlariIzle(cb: (list: Ban[]) => void): () => void {
  return onValue(
    ref(db(), 'onayli/ban'),
    (s) => {
      const v = (s.val() ?? {}) as Record<string, { until?: number; sebep?: string; ad?: string; t?: number }>;
      cb(
        Object.entries(v)
          .map(([tid, b]) => ({ tid, until: Number(b?.until) || 0, sebep: String(b?.sebep ?? ''), ad: String(b?.ad ?? ''), t: Number(b?.t) || 0 }))
          .sort((a, b) => b.t - a.t)
      );
    },
    () => cb([])
  );
}
export async function banYaz(tid: string, until: number, sebep: string, ad: string): Promise<void> {
  if (!tid || tid === 'anon' || /[.#$[\]/]/.test(tid)) throw new Error('Bu oyuncunun tarayıcı kimliği yok, banlanamıyor');
  await izinle([`ban_${tid}`], () => set(ref(db(), `onayli/ban/${tid}`), { until, sebep: sebep.slice(0, 80), ad: ad.slice(0, 24), t: serverTimestamp() }));
}
export async function banKaldir(tid: string): Promise<void> {
  await izinle([`ban_${tid}`], () => remove(ref(db(), `onayli/ban/${tid}`)));
}

// ---- the players' uploads (the game's Yükle screen: a meme photo, a pose photo, a sound, a clip) ---------------------
/** yuklemeler/<id> = { mod, ad, not, pid, isim, t, durum, tip, boyut, parca, kucuk?, bolge? }; the file itself in
 *  yukleme_veri/<id>/<n> (pieces of a data url). Approved: a meme -> onayli/meme + onayli_liste/meme, a sound ->
 *  onayli/kulak + onayli_liste/kulak (into its region's players' pack) - the same as the game's Yönetici screen. */
export type YukMod = 'meme' | 'poz' | 'kulak' | 'nediyor';
export interface Yukleme {
  id: string;
  mod: YukMod;
  ad: string;
  not: string;
  isim: string;
  t: number;
  durum: 'bekliyor' | 'onay' | 'red';
  tip: string;
  boyut: number;
  parca: number;
  kucuk?: string;
  sebep?: string;
  bolge: Bolge;
}
export function yuklemeleriIzle(cb: (list: Yukleme[]) => void): () => void {
  return onValue(
    ref(db(), 'yuklemeler'),
    (s) => {
      const v = (s.val() ?? {}) as Record<string, Record<string, unknown>>;
      cb(
        Object.entries(v)
          .filter(([, r]) => r && typeof r === 'object')
          .map(([id, r]) => ({
            id,
            mod: (['meme', 'poz', 'kulak', 'nediyor'] as YukMod[]).includes(r.mod as YukMod) ? (r.mod as YukMod) : 'meme',
            ad: String(r.ad ?? ''),
            not: String(r.not ?? ''),
            isim: String(r.isim ?? ''),
            t: Number(r.t) || 0,
            durum: (r.durum === 'onay' || r.durum === 'red' ? r.durum : 'bekliyor') as Yukleme['durum'],
            tip: String(r.tip ?? ''),
            boyut: Number(r.boyut) || 0,
            parca: Number(r.parca) || 0,
            kucuk: typeof r.kucuk === 'string' ? r.kucuk : undefined,
            sebep: typeof r.sebep === 'string' ? r.sebep : undefined,
            bolge: bolgeOf(r.bolge),
          }))
          .sort((a, b) => b.t - a.t)
      );
    },
    () => cb([])
  );
}
/** an upload's file (a data url, or a sound's JSON) */
export async function yuklemeVerisi(id: string, parca: number): Promise<string> {
  const parts = await Promise.all(Array.from({ length: parca }, (_, i) => get(ref(db(), `yukleme_veri/${id}/${i}`)).then((s) => String(s.val() ?? ''))));
  return parts.join('');
}
export async function yuklemeDurum(id: string, durum: 'onay' | 'red', sebep?: string): Promise<void> {
  // a rejected one keeps no picture (the queue can be read by anyone)
  await izinle([`y_${id}`], () => update(ref(db(), `yuklemeler/${id}`), { durum, ...(sebep ? { sebep } : {}), ...(durum === 'red' ? { kucuk: null } : {}) }));
}
export async function yuklemeDosyaSil(id: string): Promise<void> {
  await izinle([`y_${id}`], () => remove(ref(db(), `yukleme_veri/${id}`)));
}
/** the whole upload goes (the queue line and its file) */
export async function yuklemeSil(id: string): Promise<void> {
  await izinle([`y_${id}`], async () => {
    await remove(ref(db(), `yukleme_veri/${id}`));
    await remove(ref(db(), `yuklemeler/${id}`));
  });
}
/** the players' sounds of each region go into this pack ('' = "Oyuncu Sesleri") */
const OYUNCU_PAKETI: Record<Bolge, string> = { tr: '', evrensel: 'Evrensel Sesler', en: 'Player Sounds' };
export async function onayliYaz(mod: 'meme' | 'kulak', id: string, rec: Record<string, unknown>, ad: string, bolge: Bolge): Promise<void> {
  const paket = mod === 'kulak' ? OYUNCU_PAKETI[bolge] : undefined;
  await izinle([`${mod}_${id}`], async () => {
    await set(ref(db(), `onayli/${mod}/${id}`), { ...rec, bolge, ...(paket !== undefined ? { paket } : {}) });
    await set(ref(db(), `onayli_liste/${mod}/${id}`), { ad, t: serverTimestamp(), bolge, ...(paket !== undefined ? { paket } : {}) });
  });
  if (paket) {
    const key = `ses-${slugOf(paket)}`;
    await izinle([`paketbilgi_${key}`], () => update(ref(db(), `onayli/paketbilgi/${key}`), { ad: paket, bolge, emoji: '🎤' })).catch(() => undefined);
  }
}

