/** a pack's cover picture: square, 256 px, JPEG (small enough for the database; the game shows it on the pack cards) */
function kapakYap(f: File): Promise<string> {
  return new Promise((res, rej) => {
    const url = URL.createObjectURL(f);
    const img = new Image();
    img.onload = () => {
      const S = 256;
      const s = Math.min(img.naturalWidth, img.naturalHeight);
      const c = document.createElement('canvas');
      c.width = S;
      c.height = S;
      c.getContext('2d')!.drawImage(img, (img.naturalWidth - s) / 2, (img.naturalHeight - s) / 2, s, s, 0, 0, S, S);
      URL.revokeObjectURL(url);
      res(c.toDataURL('image/jpeg', 0.85));
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      rej(new Error('Resim açılamadı'));
    };
    img.src = url;
  });
}

function KapakSec({ tur, k, onMesaj }: { tur: Tur; k: Klasor; onMesaj: (m: string) => void }) {
  const [busy, setBusy] = useState(false);
  const yaz = async (resim: string | null) => {
    setBusy(true);
    try {
      await paketBilgiYaz(bilgiKey(tur, k.id), { ad: k.ad, resim });
      onMesaj(resim ? `"${k.ad}" kapak resmi değişti ✓` : `"${k.ad}" kapak resmi kaldırıldı`);
    } catch (e) {
      onMesaj(`Olmadı: ${e instanceof Error ? e.message : 'hata'}`);
    } finally {
      setBusy(false);
    }
  };
  return (
    <div className="flex items-center gap-2">
      <span className="text-xs text-[#a997be]">Kapak:</span>
      {k.resim ? <img src={k.resim} alt="" className="w-10 h-10 rounded-lg object-cover bg-black" /> : <span className="w-10 h-10 rounded-lg bg-[#2a1638] flex items-center justify-center text-xl">{k.emoji}</span>}
      <label className={`cursor-pointer rounded-lg px-2.5 py-1.5 text-xs font-bold bg-[#221330] text-[#c7b8d6] hover:text-white flex items-center gap-1 ${busy ? 'opacity-50 pointer-events-none' : ''}`}>
        <ImagePlus className="w-3.5 h-3.5" /> {k.resim ? 'Değiştir' : 'Kapak resmi seç'}
        <input
          type="file"
          accept="image/*"
          className="hidden"
          onChange={(e) => {
            const f = e.target.files?.[0];
            e.target.value = '';
            if (f) void kapakYap(f).then((d) => yaz(d), (err) => onMesaj(`Olmadı: ${err instanceof Error ? err.message : 'hata'}`));
          }}
        />
      </label>
      {k.resim && (
        <button type="button" disabled={busy} onClick={() => void yaz(null)} className="text-xs font-bold text-[#a997be] hover:text-white">
          Kaldır
        </button>
      )}
    </div>
  );
}

/*
 * OYUNCU ŞİKAYETLERİ: the players the others reported at the end of a match (the game's small flag). Every report
 * brings what that player did in that match (a few small photos, at most two of its sounds), so it can be judged after
 * the room is gone. "Suçsuz": the reports go. "Suçlu": a ban for some days or for ever (onayli/ban/<browser id>: that
 * browser can not open or join a room until then), and the reports go. Bans can be lifted below.
 */

const SEBEP_AD: Record<string, string> = {
  cinsellik: '🔞 Cinsellik / çıplaklık',
  kufur: '🤬 Küfür / hakaret',
  sabotaj: '💣 Oyunu bozma',
  nefret: '🚫 Irkçılık / nefret',
  taciz: '😠 Taciz / zorbalık',
  diger: '❓ Başka bir şey',
};
const OYUN_AD: Record<string, string> = {
  meme: 'Meme Ol!',
  nediyor: 'Ne Diyor?!',
  kulak: 'Kulaktan Kulağa',
  dev: 'Dev Uyanmasın!',
  gulme: 'Gülme Yasak!',
  goz: 'Son Göz Ayakta',
  poz: 'Poz Ver!',
};
const SURELER: { ad: string; gun: number }[] = [
  { ad: '1 gün', gun: 1 },
  { ad: '3 gün', gun: 3 },
  { ad: '7 gün', gun: 7 },
  { ad: '30 gün', gun: 30 },
  { ad: 'Süresiz', gun: 0 },
];

const tarih = (t: number) => (t ? new Date(t).toLocaleString('tr-TR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '');

/** a sound of the evidence: a Ne Diyor dub ({ sr, n: [parts], d }) or a Kulak take ({ sr, n, d }) */
function sesCal(v: Record<string, unknown>) {
  const d = typeof v.d === 'string' ? v.d : '';
  if (!d) return;
  const n = Array.isArray(v.n) || (v.n && typeof v.n === 'object') ? listeOf(v.n).reduce<number>((a, x) => a + (Number(x) || 0), 0) : Number(v.n) || 0;
  const sr = Number(v.sr) || 16000;
  if (n > 0) play(adpcmDecode(fromBase64(d), n), sr);
}

interface Grup {
  id: string;
  rt: string;
  ad: string;
  raporlar: OyuncuSikayet[];
  kim: Set<string>;
  son: number;
}

export function useOyuncuSikayetSayisi(): number {
  const [n, setN] = useState(0);
  useEffect(() => oyuncuSikayetleriIzle((l) => setN(new Set(l.map((s) => s.rt || s.r)).size)), []);
  return n;
}

export function OyuncuSikayetleri() {
  const [list, setList] = useState<OyuncuSikayet[]>([]);
  const [banlar, setBanlar] = useState<Ban[]>([]);
  const [acik, setAcik] = useState<string | null>(null);
  const [sure, setSure] = useState<Record<string, number>>({});
  const [mesaj, setMesaj] = useState<string | null>(null);
  const [mesgul, setMesgul] = useState<string | null>(null);
  useEffect(() => oyuncuSikayetleriIzle(setList), []);
  useEffect(() => banlariIzle(setBanlar), []);

  const gruplar = useMemo<Grup[]>(() => {
    const by = new Map<string, Grup>();
    for (const s of list) {
      const id = s.rt || s.r;
      const g = by.get(id) ?? { id, rt: s.rt, ad: s.ad, raporlar: [], kim: new Set<string>(), son: 0 };
      g.raporlar.push(s);
      g.kim.add(s.byt || s.by);
      g.son = Math.max(g.son, s.t);
      by.set(id, g);
    }
    return [...by.values()].sort((a, b) => b.kim.size - a.kim.size || b.son - a.son);
  }, [list]);

  const hata = (e: unknown) => setMesaj(`Olmadı: ${e instanceof Error ? e.message : 'hata'}`);

  const sucsuz = async (g: Grup) => {
    setMesgul(g.id);
    try {
      await oyuncuSikayetKapat(g.raporlar.map((r) => r.key));
      setMesaj(`"${g.ad}" suçsuz bulundu, şikayetler silindi ✓`);
    } catch (e) {
      hata(e);
    } finally {
      setMesgul(null);
    }
  };

  const suclu = async (g: Grup) => {
    const gun = sure[g.id] ?? 3;
    setMesgul(g.id);
    try {
      const sebepler = [...new Set(g.raporlar.flatMap((r) => r.sebep))].map((s) => (SEBEP_AD[s] ?? s).replace(/^\S+\s/, ''));
      await banYaz(g.rt, gun ? Date.now() + gun * 86400000 : 0, sebepler.join(', '), g.ad);
      await oyuncuSikayetKapat(g.raporlar.map((r) => r.key));
      setMesaj(`"${g.ad}" ${gun ? `${gun} gün` : 'süresiz'} banlandı ✓`);
    } catch (e) {
      hata(e);
    } finally {
      setMesgul(null);
    }
  };

  const aktifBanlar = banlar.filter((b) => b.until === 0 || b.until > Date.now());

  return (
    <div className="flex flex-col gap-3">
      <h3 className="text-xl font-black text-[#fdf8ee] flex items-center gap-2">
        <UserX className="w-5 h-5 text-[#ff8f8f]" /> Oyuncu şikayetleri
      </h3>
      <div className="text-sm text-[#a997be]">
        Maç sonunda oyuncuların şikayet ettiği kişiler. Her şikayetle o maçtaki fotoğrafları ve sesleri gelir: bak, dinle, karar ver. Karar verince şikayet ve kanıtlar silinir.
      </div>
      {mesaj && <div className="rounded-xl bg-[#5ee6a8]/10 border border-[#5ee6a8]/40 px-4 py-2 text-sm font-bold text-[#c9ffe6]">{mesaj}</div>}
      {gruplar.length === 0 && <div className="rounded-3xl bg-[#1b1028] border border-[#3e2354] p-6 text-center text-[#a997be] font-bold">Oyuncu şikayeti yok 🎉</div>}
      {gruplar.map((g) => {
        const fotolar = g.raporlar.flatMap((r) => r.foto);
        const sesler = g.raporlar.flatMap((r) => r.ses);
        const sebepler = new Map<string, number>();
        for (const r of g.raporlar) for (const s of r.sebep) sebepler.set(s, (sebepler.get(s) ?? 0) + 1);
        const notlar = g.raporlar.map((r) => r.not).filter(Boolean);
        const oyunlar = [...new Set(g.raporlar.map((r) => OYUN_AD[r.m] ?? r.m))];
        const ac = acik === g.id;
        const busy = mesgul === g.id;
        return (
          <div key={g.id} className="rounded-2xl bg-[#3a1020] border border-[#ff5a5a]/40 p-4 flex flex-col gap-3">
            <button type="button" onClick={() => setAcik(ac ? null : g.id)} className="flex flex-wrap items-center gap-2 text-left">
              <span className="text-lg">🚩</span>
              <span className="flex-1 min-w-0 truncate font-black text-[#fdf8ee] text-lg">{g.ad}</span>
              <span className="text-sm font-black text-[#ff8f8f]">{g.kim.size} kişi şikayet etti</span>
              <span className="text-xs text-[#a997be]">{oyunlar.join(', ')} · {tarih(g.son)}</span>
            </button>
            <div className="flex flex-wrap gap-1.5">
              {[...sebepler.entries()].map(([s, n]) => (
                <span key={s} className="rounded-full bg-[#ff5a5a]/20 text-[#ffc2c2] text-xs font-bold px-2.5 py-1">
                  {SEBEP_AD[s] ?? s}
                  {n > 1 ? ` ×${n}` : ''}
                </span>
              ))}
            </div>
            {(ac || fotolar.length <= 4) && fotolar.length > 0 && (
              <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
                {fotolar.map((f, i) => (
                  <a key={i} href={f} target="_blank" rel="noreferrer">
                    <img src={f} alt="" className="w-full aspect-square object-cover rounded-lg bg-black" />
                  </a>
                ))}
              </div>
            )}
            {!ac && fotolar.length > 4 && (
              <button type="button" onClick={() => setAcik(g.id)} className="self-start text-xs font-bold text-[#ffd166]">
                {fotolar.length} fotoğrafı göster
              </button>
            )}
            {sesler.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {sesler.map((s, i) => (
                  <button key={i} type="button" onClick={() => sesCal(s.v)} className="rounded-lg bg-[#221330] px-3 py-1.5 text-xs font-bold text-[#c7b8d6] hover:text-white flex items-center gap-1.5">
                    <Play className="w-3.5 h-3.5 fill-current" /> {s.k === 'dublaj' ? 'Dublajını dinle' : 'Sesini dinle'} {sesler.length > 1 ? i + 1 : ''}
                  </button>
                ))}
              </div>
            )}
            {notlar.length > 0 && (
              <div className="flex flex-col gap-1">
                {notlar.map((n, i) => (
                  <div key={i} className="rounded-lg bg-black/25 px-3 py-1.5 text-sm text-[#fdf8ee]">
                    “{n}”
                  </div>
                ))}
              </div>
            )}
            {g.raporlar[0]?.oda && <div className="text-xs text-[#a997be]">Oda: {[...new Set(g.raporlar.map((r) => r.oda))].join(', ')}</div>}
            <div className="flex flex-wrap items-center gap-2 pt-1 border-t border-white/10">
              <button type="button" disabled={busy} onClick={() => void sucsuz(g)} className="rounded-lg px-3 py-2 text-sm font-black bg-[#5ee6a8]/20 text-[#c9ffe6] hover:bg-[#5ee6a8]/30 flex items-center gap-1.5 disabled:opacity-50">
                <ShieldCheck className="w-4 h-4" /> Suçsuz
              </button>
              <span className="ml-auto text-xs font-bold text-[#a997be]">Ceza:</span>
              <select
                value={sure[g.id] ?? 3}
                onChange={(e) => setSure({ ...sure, [g.id]: Number(e.target.value) })}
                className="bg-[#120a1a] border border-[#ff5a5a]/40 rounded-lg px-2 py-2 text-sm font-bold text-[#fdf8ee]"
              >
                {SURELER.map((s) => (
                  <option key={s.gun} value={s.gun}>
                    {s.ad}
                  </option>
                ))}
              </select>
              <button type="button" disabled={busy || !g.rt} onClick={() => void suclu(g)} className="rounded-lg px-3 py-2 text-sm font-black bg-[#ff5a5a] text-white hover:brightness-110 flex items-center gap-1.5 disabled:opacity-50" title={g.rt ? '' : 'Bu oyuncunun tarayıcı kimliği yok'}>
                <Gavel className="w-4 h-4" /> Suçlu: banla
              </button>
            </div>
          </div>
        );
      })}

      <h3 className="text-lg font-black text-[#fdf8ee] flex items-center gap-2 mt-2">
        <BanIkon className="w-5 h-5 text-[#ffd166]" /> Banlılar ({aktifBanlar.length})
      </h3>
      {aktifBanlar.length === 0 ? (
        <div className="text-sm text-[#a997be]">Şu an banlı kimse yok.</div>
      ) : (
        <div className="flex flex-col gap-2">
          {aktifBanlar.map((b) => (
            <div key={b.tid} className="flex flex-wrap items-center gap-2 rounded-xl bg-[#1b1028] border border-[#3e2354] px-4 py-2">
              <span className="font-bold text-[#fdf8ee]">{b.ad || b.tid}</span>
              <span className="text-xs text-[#a997be]">{b.sebep}</span>
              <span className="ml-auto text-xs font-bold text-[#ffd166]">{b.until ? `${tarih(b.until)} tarihine kadar` : 'süresiz'}</span>
              <button
                type="button"
                onClick={() => void banKaldir(b.tid).then(() => setMesaj(`"${b.ad || b.tid}" banı kaldırıldı ✓`), hata)}
                className="rounded-lg px-3 py-1.5 text-xs font-bold bg-[#221330] text-[#c7b8d6] hover:text-white flex items-center gap-1"
              >
                <Check className="w-3.5 h-3.5" /> Banı kaldır
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

