import React, { useEffect, useState } from 'react';
import { ImagePlus, Loader2, Trash2 } from 'lucide-react';
import { MemeGelen, memeGelenIzle, memeGelenSil, memeGonder } from './paketVeri';

import React, { useEffect, useMemo, useState } from 'react';
import { Check, Download, ImagePlus, Inbox, Loader2, Play, Sparkles, Trash2, X } from 'lucide-react';
import { MemeGelen, Yukleme, memeGelenIzle, memeGelenSil, memeGonder, onayliYaz, yuklemeDosyaSil, yuklemeDurum, yuklemeSil, yuklemeVerisi, yuklemeleriIzle } from './paketVeri';
import { adpcmDecode, fromBase64, play } from '../ses/ses';
import { BolgeIkon } from './Bolge';

