/*
 * YÜKLENENLER: what the players sent from the game's "Yükle" screen (a meme photo, a pose photo, a funny sound, a clip),
 * waiting for you. Open one, look / listen, then:
 *   a meme   "Claude işlesin" (into Meme Ol's queue: Claude makes its file with the face points - the best way) or
 *            "Direkt onayla" (the photo goes into the game as it is), or "Reddet"
 *   a sound  "Onayla" (into its region's players' pack in Kulaktan Kulağa) or "Reddet"
 *   a pose   reading the body from the photo needs the game: approve it in the game's Yönetici screen (or reject here)
 *   a clip   "İndir": put it into a pack with the Ne Diyor tab (its silent parts must be marked), then "Tamamlandı"
 */

const MOD: Record<Yukleme['mod'], { ad: string; emoji: string }> = {
  meme: { ad: 'Meme Ol', emoji: '😜' },
  poz: { ad: 'Poz Ver', emoji: '🕺' },
  kulak: { ad: 'Kulak', emoji: '🎤' },
  nediyor: { ad: 'Ne Diyor', emoji: '🎬' },
};
const tarih = (t: number) => (t ? new Date(t).toLocaleString('tr-TR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '');

export function useYuklemeSayisi(): number {
  const [n, setN] = useState(0);
  useEffect(() => yuklemeleriIzle((l) => setN(l.filter((u) => u.durum === 'bekliyor').length)), []);
  return n;
}

function Satir({ u }: { u: Yukleme }) {
  const [data, setData] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [sebep, setSebep] = useState('');
  const [silOnay, setSilOnay] = useState(false);
  const m = MOD[u.mod];

  const hata = (e: unknown) => setMsg(`Olmadı: ${e instanceof Error ? e.message : 'hata'}`);
  const is = async (f: () => Promise<void>) => {
    setBusy(true);
    setMsg(null);
    try {
      await f();
    } catch (e) {
      hata(e);
    } finally {
      setBusy(false);
    }
  };

  const ac = () =>
    is(async () => {
      const d = await yuklemeVerisi(u.id, u.parca);
      if (d.length !== u.boyut) {
        setMsg(Date.now() - u.t < 10 * 60000 ? 'Bu dosya hâlâ yükleniyor: birkaç dakika sonra tekrar aç.' : 'Bu yükleme yarım kalmış (gönderenin bağlantısı kopmuş): sadece silinebilir.');
        return;
      }
      setData(d);
    });

  const sesiCal = () => {
    if (!data) return;
    try {
      const s = JSON.parse(data) as { sr: number; n: number; d: string };
      play(adpcmDecode(fromBase64(s.d), s.n), s.sr);
    } catch {
      setMsg('Ses açılamadı');
    }
  };

  /** approved and copied into the game: the uploaded file goes (a clip stays: it still goes into a pack by hand) */
  const bitti = async (dosyaSil: boolean) => {
    await yuklemeDurum(u.id, 'onay');
    if (dosyaSil) await yuklemeDosyaSil(u.id);
  };

  const claudeIslesin = () =>
    is(async () => {
      if (!data) return;
      await memeGonder(u.ad || 'meme', data);
      await bitti(true);
      setMsg('Meme Ol sırasına girdi ✓ Claude\'a "memeleri işle" de.');
    });
  const direktOnay = () =>
    is(async () => {
      if (!data) return;
      if (u.mod === 'meme') await onayliYaz('meme', u.id, { ad: u.ad, foto: data }, u.ad, u.bolge);
      else if (u.mod === 'kulak') {
        const s = JSON.parse(data) as { sr: number; n: number; d: string };
        await onayliYaz('kulak', u.id, { ad: u.ad, sr: s.sr, n: s.n, d: s.d }, u.ad, u.bolge);
      }
      await bitti(true);
      setMsg('Oyuna eklendi ✓');
    });
  const tamam = () =>
    is(async () => {
      await bitti(false);
      setMsg('Tamamlandı olarak işaretlendi ✓');
    });
  const reddet = () =>
    is(async () => {
      await yuklemeDurum(u.id, 'red', sebep.trim() || undefined);
      await yuklemeDosyaSil(u.id);
    });
  const tamamenSil = () => {
    if (!silOnay) return setSilOnay(true);
    setSilOnay(false);
    void is(() => yuklemeSil(u.id));
  };
  const indir = () => {
    if (!data) return;
    const a = document.createElement('a');
    a.href = data;
    a.download = `${u.ad || u.id}.${u.tip.split('/')[1] || 'bin'}`;
    a.click();
  };

  const bekliyor = u.durum === 'bekliyor';
  return (
    <div className={`rounded-2xl border p-3 flex flex-col gap-2 ${bekliyor ? 'bg-[#1b1028] border-[#3e2354]' : 'bg-[#140c1c] border-[#2a1a3a] opacity-80'}`}>
      <div className="flex items-center gap-3">
        {u.kucuk ? <img src={u.kucuk} alt="" className="w-16 h-16 rounded-xl object-cover bg-black flex-none" /> : <span className="w-16 h-16 rounded-xl bg-[#2a1638] flex items-center justify-center text-3xl flex-none">{m.emoji}</span>}
        <div className="flex-1 min-w-0 flex flex-col">
          <span className="font-black text-[#fdf8ee] truncate">{u.ad || '(adsız)'}</span>
          <span className="text-xs text-[#a997be] truncate">
            {m.emoji} {m.ad} · {u.isim || 'Oyuncu'} · {tarih(u.t)}
          </span>
          {u.not && <span className="text-xs text-[#c7b8d6] truncate">“{u.not}”</span>}
        </div>
        <BolgeIkon b={u.bolge} />
        <span className={`text-xs font-black px-2 py-1 rounded-full ${bekliyor ? 'bg-[#ffd166]/20 text-[#ffd166]' : u.durum === 'onay' ? 'bg-[#5ee6a8]/20 text-[#5ee6a8]' : 'bg-[#ff5a5a]/20 text-[#ff8f8f]'}`}>
          {bekliyor ? 'bekliyor' : u.durum === 'onay' ? 'onaylandı' : 'reddedildi'}
        </span>
      </div>

      {bekliyor && !data && (
        <button type="button" disabled={busy} onClick={() => void ac()} className="self-start rounded-lg px-3 py-1.5 text-sm font-bold bg-[#ff4b82] text-white flex items-center gap-1.5 disabled:opacity-50">
          {busy ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />} Aç, bak
        </button>
      )}

      {data && bekliyor && (
        <div className="flex flex-col gap-2">
          {(u.mod === 'meme' || u.mod === 'poz') && <img src={data} alt="" className="max-h-80 w-auto self-start rounded-xl bg-black" />}
          {u.mod === 'nediyor' && <video src={data} controls className="max-h-80 w-auto self-start rounded-xl bg-black" />}
          {u.mod === 'kulak' && (
            <button type="button" onClick={sesiCal} className="self-start rounded-lg px-3 py-1.5 text-sm font-bold bg-[#221330] text-[#fdf8ee] flex items-center gap-1.5">
              <Play className="w-4 h-4 fill-current" /> Dinle
            </button>
          )}
          <div className="flex flex-wrap gap-2">
            {u.mod === 'meme' && (
              <>
                <button type="button" disabled={busy} onClick={() => void claudeIslesin()} className="rounded-lg px-3 py-1.5 text-sm font-black bg-gradient-to-r from-[#ffd166] to-[#ffb703] text-[#1a0f26] flex items-center gap-1.5 disabled:opacity-50">
                  <Sparkles className="w-4 h-4" /> Claude işlesin
                </button>
                <button type="button" disabled={busy} onClick={() => void direktOnay()} className="rounded-lg px-3 py-1.5 text-sm font-bold bg-[#5ee6a8]/20 text-[#c9ffe6] flex items-center gap-1.5 disabled:opacity-50">
                  <Check className="w-4 h-4" /> Direkt onayla
                </button>
              </>
            )}
            {u.mod === 'kulak' && (
              <button type="button" disabled={busy} onClick={() => void direktOnay()} className="rounded-lg px-3 py-1.5 text-sm font-black bg-[#5ee6a8] text-[#160d1f] flex items-center gap-1.5 disabled:opacity-50">
                <Check className="w-4 h-4" /> Onayla
              </button>
            )}
            {u.mod === 'nediyor' && (
              <button type="button" disabled={busy} onClick={() => void tamam()} className="rounded-lg px-3 py-1.5 text-sm font-bold bg-[#5ee6a8]/20 text-[#c9ffe6] flex items-center gap-1.5 disabled:opacity-50">
                <Check className="w-4 h-4" /> Pakete ekledim, tamamlandı
              </button>
            )}
            {(u.mod === 'nediyor' || u.mod === 'poz' || u.mod === 'meme') && (
              <button type="button" onClick={indir} className="rounded-lg px-3 py-1.5 text-sm font-bold bg-[#221330] text-[#c7b8d6] hover:text-white flex items-center gap-1.5">
                <Download className="w-4 h-4" /> İndir
              </button>
            )}
          </div>
          {u.mod === 'poz' && <div className="text-xs text-[#ffd166]">Poz için vücut okuması oyunda yapılıyor: bunu oyunun Yönetici ekranından onayla (ya da buradan reddet).</div>}
          {u.mod === 'nediyor' && <div className="text-xs text-[#ffd166]">Videoyu indir, Ne Diyor sekmesinde sessiz yerlerini işaretleyip bir pakete gönder, sonra "tamamlandı" de.</div>}
          <div className="flex flex-wrap items-center gap-2">
            <input value={sebep} onChange={(e) => setSebep(e.target.value)} maxLength={80} placeholder="Ret sebebi (oyuncu görür, boş olabilir)" className="flex-1 min-w-[180px] bg-[#120a1a] border border-[#3e2354] rounded-lg px-2 py-1.5 text-sm text-[#fdf8ee]" />
            <button type="button" disabled={busy} onClick={() => void reddet()} className="rounded-lg px-3 py-1.5 text-sm font-bold bg-[#ff5a5a]/20 text-[#ff8f8f] hover:text-white flex items-center gap-1.5 disabled:opacity-50">
              <X className="w-4 h-4" /> Reddet
            </button>
          </div>
        </div>
      )}

      <div className="flex items-center gap-2">
        {msg && <span className="flex-1 text-sm font-bold text-[#c9ffe6]">{msg}</span>}
        {!bekliyor && u.sebep && <span className="flex-1 text-xs text-[#a997be]">Sebep: {u.sebep}</span>}
        <button type="button" onClick={tamamenSil} className={`ml-auto rounded-lg px-2 py-1 text-xs font-bold flex items-center gap-1 ${silOnay ? 'bg-[#ff5a5a] text-white' : 'text-[#a997be] hover:text-white'}`} title="Listeden tamamen sil">
          <Trash2 className="w-3.5 h-3.5" /> {silOnay ? 'Emin misin? Sil' : ''}
        </button>
      </div>
    </div>
  );
}

export function Yuklenenler() {
  const [list, setList] = useState<Yukleme[] | null>(null);
  const [filtre, setFiltre] = useState<'hepsi' | Yukleme['mod']>('hepsi');
  const [eskiler, setEskiler] = useState(false);
  useEffect(() => yuklemeleriIzle(setList), []);
  const gorunen = useMemo(() => (list ?? []).filter((u) => (filtre === 'hepsi' || u.mod === filtre) && (eskiler || u.durum === 'bekliyor')), [list, filtre, eskiler]);
  const say = (mod: Yukleme['mod']) => (list ?? []).filter((u) => u.mod === mod && u.durum === 'bekliyor').length;

  return (
    <div className="max-w-5xl mx-auto w-full flex flex-col gap-4">
      <h2 className="text-2xl font-black text-[#fdf8ee] flex items-center gap-2">
        <Inbox className="w-6 h-6 text-[#5cc8ff]" /> Yüklenenler
      </h2>
      <div className="text-sm text-[#a997be]">Oyuncuların oyundaki "Yükle" ekranından gönderdikleri: memeler, pozlar, sesler, videolar. Aç, bak, onayla ya da reddet.</div>
      <div className="flex flex-wrap items-center gap-2">
        {(['hepsi', 'meme', 'kulak', 'poz', 'nediyor'] as const).map((f) => (
          <button
            key={f}
            type="button"
            onClick={() => setFiltre(f)}
            className={`rounded-xl px-3 py-1.5 text-sm font-bold ${filtre === f ? 'bg-[#5cc8ff] text-[#160d1f]' : 'bg-[#1b1028] text-[#a997be] hover:text-white'}`}
          >
            {f === 'hepsi' ? 'Hepsi' : `${MOD[f].emoji} ${MOD[f].ad}`}
            {f !== 'hepsi' && say(f) > 0 ? ` (${say(f)})` : ''}
          </button>
        ))}
        <label className="ml-auto flex items-center gap-2 text-sm text-[#a997be]">
          <input type="checkbox" checked={eskiler} onChange={(e) => setEskiler(e.target.checked)} /> Onaylanan / reddedilenleri de göster
        </label>
      </div>
      {list === null && <div className="text-[#a997be] font-bold">Yükleniyor…</div>}
      {list && gorunen.length === 0 && <div className="rounded-3xl bg-[#1b1028] border border-[#3e2354] p-8 text-center text-[#a997be] font-bold">Bekleyen yükleme yok 🎉</div>}
      {gorunen.map((u) => (
        <Satir key={u.id} u={u} />
      ))}
    </div>
  );
}
